import random,itertools
from fractions import Fraction
for L in range(0,9):
 for trial in range(1000):
  ps=[]
  for _ in range(L):
   vals=[random.randint(0,10) for _ in range(3)]
   if sum(vals)==0:vals[0]=1
   ps.append(tuple(Fraction(x,sum(vals)) for x in vals))
  if L==0: dp=Fraction(1)
  else:
   up,pe,dn=Fraction(1),Fraction(0),Fraction(0)
   for u,h,d in ps: up,pe,dn=up*u,up*h,(up+pe+dn)*d
   dp=up+pe+dn
  total=Fraction(0)
  if L==0: total=Fraction(1)
  else:
   for seq in itertools.product(range(3),repeat=L):
    # valid if seq is U*D* or U*H D*
    s=seq
    # A
    ok=True; seenD=False
    for x in s:
     if x==2:seenD=True
     elif x==1:ok=False;break
     elif seenD:ok=False;break
    if ok:
     w=Fraction(1)
     for x,p in zip(s,ps):w*=p[x]
     total+=w;continue
    # B exactly one H, all U before, all D after
    if s.count(1)==1:
     k=s.index(1)
     if all(x==0 for x in s[:k]) and all(x==2 for x in s[k+1:]):
      w=Fraction(1)
      for x,p in zip(s,ps):w*=p[x]
      total+=w
  if total!=dp:
   print('bad',L,ps,total,dp);raise SystemExit
print('dp enumeration okay')
